[ExtensionOf(classStr(SalesInvoiceJournalPost))]
public final class GUPSalesInvoiceJournalPost_Extension
{
    private RecId gupPriceTreeRecId;
    private GUPEnablePriceTree priceTreeEnabled;

}

Method.Source:
public void init()
{
    next init();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        gupPriceTreeRecId = GUPPricingTree::find(GUPPricingTree::findPriceTreeNameBySalesId(salesTable.SalesId)).RecId;
        priceTreeEnabled = GUPParameters::find().EnablePriceTree;
    }

    return;
}

protected boolean shouldPostRetailDiscountsForNormalOrders()
{
    next shouldPostRetailDiscountsForNormalOrders();

    boolean ret = FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) && RetailSalesTable::findSalesTable(salesTable);

    if (ret && salesLine.RevRecRevenueScheduleID)
    {
        info("@GlobalUnifiedPricing:UseStandardSalesLineDiscountPostingWithRevRecRevenueScheduleIDSet");
        ret = false;
    }

    return ret;
}

protected boolean shouldProcessDiscountLineLevelPostings(RetailPeriodicDiscount _retailPeriodicDiscount)
{
    boolean ret = true;

    GUPPriceComponentCodeSetup priceComponentCodeSetup;

    if (_retailPeriodicDiscount.Status != RetailDisabledEnabled::Enabled ||
            !_retailPeriodicDiscount.IsGupDiscount)
    {
        return false;
    }

    select firstonly RecId, PostInLedger, PriceComponentCodeName from priceComponentCodeSetup
        where priceComponentCodeSetup.PriceComponentCodeName == _retailPeriodicDiscount.PriceComponentCodeName
            && (!priceTreeEnabled || (priceComponentCodeSetup.PricingTree == gupPriceTreeRecId));
    if (!priceComponentCodeSetup.RecId || !priceComponentCodeSetup.PostInLedger)
    {
        return false;
    }

    return ret;
}

protected void processDiscountLineLevelPostings(RetailSalesDiscountLine _retailSalesDiscountLine, LedgerVoucherObject _ledgerVoucherObject, LedgerDimensionAccount _defaultDimension, LedgerDimensionAccount _ledgerDimensionPeriodicDiscount, Amount _periodicDiscountAmount, CurrencyExchangeHelper _exchangeRateHelper, int _sign)
{
    next processDiscountLineLevelPostings(_retailSalesDiscountLine, _ledgerVoucherObject, _defaultDimension, _ledgerDimensionPeriodicDiscount, _periodicDiscountAmount, _exchangeRateHelper, _sign);

    if (!FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        return;
    }

    RetailPeriodicDiscount                  retailPeriodicDiscount;
    GUPPeriodicDiscountAllocation           lineAllocation;
    GUPPeriodicDiscountClaimDistribution    lineClaim;
    GUPPriceComponentCodeSetup              priceComponentCodeSetup;
    GUPDiscountVendorClaimPostingProfile    discountVendorClaimPostingProfile;
    GUPDiscountAllocationPostingProfile     discountAllocationPostingProfile;

    select firstonly retailPeriodicDiscount
        where retailPeriodicDiscount.OfferId == _retailSalesDiscountLine.PeriodicDiscountOfferId
        join RecId, PostInLedger, PriceComponentCodeName, LedgerDimension from priceComponentCodeSetup
            where priceComponentCodeSetup.PriceComponentCodeName == retailPeriodicDiscount.PriceComponentCodeName
                && (!priceTreeEnabled || (priceComponentCodeSetup.PricingTree == gupPriceTreeRecId));

    if (!this.shouldProcessDiscountLineLevelPostings(retailPeriodicDiscount))
    {
        return;
    }

    LedgerDimensionAccount discountLineAccount = _ledgerDimensionPeriodicDiscount;

    if (retailPeriodicDiscount is RetailDiscountOffer)
    {
        select count(RecId) from lineClaim
            where lineClaim.OfferId == retailPeriodicDiscount.OfferId
                && lineClaim.LineNum == _retailSalesDiscountLine.AppliedDiscountLineNum;

        select count(RecId) from lineAllocation
            where lineAllocation.OfferId == retailPeriodicDiscount.OfferId
                && lineAllocation.LineNum == _retailSalesDiscountLine.AppliedDiscountLineNum;

        Amount totalValue = 0.0;

        RetailDiscountLineOffer lineOffer;

        select lineOffer where lineOffer.OfferId == retailPeriodicDiscount.OfferId
            && lineOffer.LineNum == _retailSalesDiscountLine.AppliedDiscountLineNum;

        if (lineOffer.discountMethod == RetailDiscountOfferLineDiscMethodBase::AmountOff)
        {
            totalValue = lineOffer.discAmount;
        }
        else if (lineOffer.discountMethod == RetailDiscountOfferLineDiscMethodBase::PercentOff)
        {
            totalValue = lineOffer.discPct;
        }

        // If total discount splitting amount = 100% of discount value, make sure no amount is left after each split is rounded.
        if (this.checkPercentageFullSplitRequired(retailPeriodicDiscount, _retailSalesDiscountLine.AppliedDiscountLineNum))
        {
            int totalSplits = lineClaim.RecId + lineAllocation.RecId;
            int currentSplit = 0;
            Amount currentSum = 0.0;

            while select DiscountPercentOrValue from lineClaim
                where lineClaim.OfferId == retailPeriodicDiscount.OfferId
                    && lineClaim.LineNum == _retailSalesDiscountLine.AppliedDiscountLineNum
                join discountVendorClaimPostingProfile
                    where discountVendorClaimPostingProfile.Name == lineClaim.PostingProfile
            {
                currentSplit++;
                currentSum += this.addSplitAmount(_ledgerVoucherObject,
                                                    formletterProvider.postingTypeLineDiscount(),
                                                    retailPeriodicDiscount.OfferId,
                                                    discountVendorClaimPostingProfile,
                                                    _defaultDimension,
                                                    discountLineAccount,
                                                    _exchangeRateHelper,
                                                    _periodicDiscountAmount,
                                                    currentSplit,
                                                    totalSplits,
                                                    currentSum,
                                                    totalValue,
                                                    lineClaim.DiscountPercentOrValue,
                                                    _sign);
            }

            while select DiscountPercentOrValue from lineAllocation
                where lineAllocation.OfferId == retailPeriodicDiscount.OfferId
                    && lineAllocation.LineNum == _retailSalesDiscountLine.AppliedDiscountLineNum
                join discountAllocationPostingProfile
                    where discountAllocationPostingProfile.Name == lineAllocation.PostingProfile
            {
                currentSplit++;
                currentSum += this.addSplitAmount(_ledgerVoucherObject,
                                                  formletterProvider.postingTypeLineDiscount(),
                                                  retailPeriodicDiscount.OfferId,
                                                  discountAllocationPostingProfile,
                                                  _defaultDimension,
                                                  discountLineAccount,
                                                  _exchangeRateHelper,
                                                  _periodicDiscountAmount,
                                                  currentSplit,
                                                  totalSplits,
                                                  currentSum,
                                                  totalValue,
                                                  lineAllocation.DiscountPercentOrValue,
                                                  _sign);
            }
        }
        else
        {
            while select DiscountPercentOrValue from lineAllocation
                where lineAllocation.OfferId == retailPeriodicDiscount.OfferId
                    && lineAllocation.LineNum == _retailSalesDiscountLine.AppliedDiscountLineNum
                join discountAllocationPostingProfile
                    where discountAllocationPostingProfile.Name == lineAllocation.PostingProfile
            {
                Amount splitAmount = round(lineAllocation.DiscountPercentOrValue / totalValue * _periodicDiscountAmount, 0.01);

                this.addledgerVoucherTransPairByPostingProfile(_ledgerVoucherObject,
                                                               formletterProvider.postingTypeLineDiscount(),
                                                               retailPeriodicDiscount.OfferId,
                                                               discountAllocationPostingProfile,
                                                               _defaultDimension,
                                                               discountLineAccount,
                                                               splitAmount * _sign,
                                                               _exchangeRateHelper);
            }

            while select DiscountPercentOrValue from lineClaim
                where lineClaim.OfferId == retailPeriodicDiscount.OfferId
                    && lineClaim.LineNum == _retailSalesDiscountLine.AppliedDiscountLineNum
                join discountVendorClaimPostingProfile
                    where discountVendorClaimPostingProfile.Name == lineClaim.PostingProfile
            {
                Amount splitAmount = round(lineClaim.DiscountPercentOrValue / totalValue * _periodicDiscountAmount, 0.01);

                this.addledgerVoucherTransPairByPostingProfile(_ledgerVoucherObject,
                                                                formletterProvider.postingTypeLineDiscount(),
                                                                retailPeriodicDiscount.OfferId,
                                                                discountVendorClaimPostingProfile,
                                                                _defaultDimension,
                                                                discountLineAccount,
                                                                splitAmount * _sign,
                                                                _exchangeRateHelper);
            }
        }
    }

}

protected LedgerDimensionDefaultAccount getLedgerAccountForPeriodicDisc(RetailSalesDiscountLine _retailSalesDiscountLine, SalesLine _salesLine, SalesTable _salesTable)
{
    LedgerDimensionDefaultAccount defaultAccount = next getLedgerAccountForPeriodicDisc(_retailSalesDiscountLine, _salesLine, _salesTable);
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        RetailParameters postingRetailSetup = RetailParameters::find();
        if (postingRetailSetup.LedgerAccountType == RetailBookingLedgerAccountTypeBase::Periodic)
        {
            GUPPriceComponentCodeSetup priceComponentCodeSetup;
            RetailPeriodicDiscount periodicDiscount;

            select firstonly RecId, PostInLedger, PriceComponentCodeName, LedgerDimension from priceComponentCodeSetup
                join DiscountLedgerDimension, PriceComponentCodeName from periodicDiscount
                where periodicDiscount.OfferId == _retailSalesDiscountLine.PeriodicDiscountOfferId
                    && periodicDiscount.PriceComponentCodeName == priceComponentCodeSetup.PriceComponentCodeName
                    && (!priceTreeEnabled || (priceComponentCodeSetup.PricingTree == gupPriceTreeRecId));

            if (!periodicDiscount.DiscountLedgerDimension && priceComponentCodeSetup.RecId && priceComponentCodeSetup.LedgerDimension)
            {
                defaultAccount = priceComponentCodeSetup.LedgerDimension;
            }
        }
    }

    return defaultAccount;

}

private Amount addSplitAmount(LedgerVoucherObject _ledgerVoucherObject,
                              LedgerPostingType _ledgerPostingType,
                              RetailPeriodicDiscountOfferId _discountOfferId,
                              Common _postingProfile,
                              LedgerDimensionAccount _defaultDimension,
                              LedgerDimensionAccount _discountLineAccount,
                              CurrencyExchangeHelper _exchangeRateHelper, 
                              Amount _periodicDiscountAmount, 
                              int _currentSplit, 
                              int _totalSplits, 
                              Amount _currentSum,
                              Amount _totalValue,
                              Amount _discountPercentOrValue,
                              int _sign)
{
    Amount splitAmount;

    if (_currentSplit == _totalSplits)
    {
        splitAmount = _periodicDiscountAmount - _currentSum;
    }
    else
    {
        splitAmount = round(_discountPercentOrValue / _totalValue * _periodicDiscountAmount, 0.01);
    }

    this.addledgerVoucherTransPairByPostingProfile(_ledgerVoucherObject,
                                                   _ledgerPostingType,
                                                   _discountOfferId,
                                                   _postingProfile,
                                                   _defaultDimension,
                                                   _discountLineAccount,
                                                   splitAmount * _sign,
                                                   _exchangeRateHelper);

    return splitAmount;
}

protected boolean checkPercentageFullSplitRequired(RetailPeriodicDiscount _retailPeriodicDiscount, real _lineNum = 0.0, real _tier = 0.0)
{
    // Special handling is necessary for full percentage splits.
    GUPPeriodicDiscountAllocation           lineAllocation;
    GUPPeriodicDiscountClaimDistribution    lineClaim;

    if (_retailPeriodicDiscount is RetailDiscountOffer)
    {
        RetailDiscountLineOffer discLine;

        select firstonly discountMethod, OfferId, LineNum, discPct from discLine where
            discLine.OfferId == _retailPeriodicDiscount.OfferId
                && discLine.LineNum == _lineNum;

        if (discLine.discountMethod == RetailDiscountOfferLineDiscMethodBase::PercentOff)
        {
            select sum(DiscountPercentOrValue) from lineClaim
                where lineClaim.OfferId == discLine.OfferId
                    && lineClaim.LineNum == discLine.LineNum;

            select sum(DiscountPercentOrValue) from lineAllocation
                where lineAllocation.OfferId == discLine.OfferId
                    && lineAllocation.LineNum == discLine.LineNum;

            if (lineClaim.DiscountPercentOrValue + lineAllocation.DiscountPercentOrValue == discLine.discPct)
            {
                return true;
            }
        }
    }

    return false;
}

protected void addledgerVoucherTransPairByPostingProfile(LedgerVoucherObject _ledgerVoucherObject,
                                                         LedgerPostingType _ledgerPostingType,
                                                         RetailPeriodicDiscountOfferId _discountOfferId,
                                                         Common _postingProfile,
                                                         LedgerDimensionAccount _defaultDimension,
                                                         LedgerDimensionAccount _discountLineAccount,
                                                         Amount _amount, 
                                                         CurrencyExchangeHelper _exchangeRateHelper)
{
    LedgerDimensionAccount debitAccount;

    if (_postingProfile is GUPDiscountAllocationPostingProfile)
    {
        GUPDiscountAllocationPostingProfile discountAllocationPostingProfile = _postingProfile;
        debitAccount = LedgerDimensionFacade::serviceCreateLedgerDimension(discountAllocationPostingProfile.DebitAccount, _defaultDimension);
    }
    else if (_postingProfile is GUPDiscountVendorClaimPostingProfile)
    {
        GUPDiscountVendorClaimPostingProfile discountVendorClaimPostingProfile = _postingProfile;
        debitAccount = LedgerDimensionFacade::serviceCreateLedgerDimension(discountVendorClaimPostingProfile.DebitAccount, _defaultDimension);

        // Generate transactions for vendor claim.
        this.createClaimAccruals(_ledgerVoucherObject,
                                 _discountOfferId,
                                 _ledgerPostingType,
                                 discountVendorClaimPostingProfile,
                                 discountVendorClaimPostingProfile.DebitAccount,
                                 _amount);
    }

    this.addledgerVoucherTransPair(_ledgerVoucherObject,
                                   _ledgerPostingType,
                                   _discountLineAccount,
                                   debitAccount,
                                   _amount,
                                   _exchangeRateHelper);
}

protected void createClaimAccruals(LedgerVoucherObject _ledgerVoucherObject,
                                   RetailPeriodicDiscountOfferId _discountOfferId,
                                   LedgerPostingType _ledgerPostingType,
                                   GUPDiscountVendorClaimPostingProfile _claimPostingProfile,
                                   LedgerDimensionAccount _accrualAccount,
                                   Amount _amount)
{
    GUPDiscountClaim            gupDiscountClaim;
    GUPDiscountClaimTransaction gupDiscountClaimTransaction;
    ItemId                      itemId                      = this.inventTable.ItemId;
    InventItemSalesSetup        inventItemSalesSetup        = InventItemSalesSetup::find(itemId, custInvoiceTrans.InventDimId);
    VendAccount                 claimVendorAccount          = inventItemSalesSetup.GUPDiscountClaimVendorAccount;

    // Claim vendor account is not set.
    if (!claimVendorAccount)
    {
        warning(strFmt("@GlobalUnifiedPricing:VendorAccountForClaimNotSetOnItem", itemId));
        throw error("@SYS21533");
    }

    select firstonly RecId, DiscountClaimId from gupDiscountClaim 
        where  gupDiscountClaim.SalesInvoice    == custInvoiceJour.InvoiceId
            && gupDiscountClaim.DiscountId      == _discountOfferId
            && gupDiscountClaim.LedgerDimension == _accrualAccount
            && gupDiscountClaim.VendorAccount   == claimVendorAccount;

    // If there is already a claim created for this, add transactions to it without creating new claim.
    if (!gupDiscountClaim.RecId)
    {
        gupDiscountClaim.DiscountClaimId = NumberSeq::newGetNum(GUPParameters::numRefDiscountClaimId()).num();
        gupDiscountClaim.DiscountId      = _discountOfferId;
        gupDiscountClaim.VendorAccount   = claimVendorAccount;
        gupDiscountClaim.SalesInvoice    = custInvoiceJour.InvoiceId;
        gupDiscountClaim.CurrencyCode    = salesLine.CurrencyCode;
        gupDiscountClaim.LedgerDimension = _accrualAccount;
        gupDiscountClaim.Status          = GUPDiscountClaimStatus::Calculated;
        gupDiscountClaim.insert();
    }

    // If there is already a claim transaction for this inventTransId, only add claim amount to it.
    select firstonly RecId, Amount from gupDiscountClaimTransaction
        where  gupDiscountClaimTransaction.DiscountClaimId  == gupDiscountClaim.DiscountClaimId
            && gupDiscountClaimTransaction.ItemNumber       == itemId
            && gupDiscountClaimTransaction.InventTransId    == salesLine.InventTransId;

    if (!gupDiscountClaimTransaction.RecId)
    {
        gupDiscountClaimTransaction.DiscountClaimId = gupDiscountClaim.DiscountClaimId;
        gupDiscountClaimTransaction.Amount          = _amount;
        gupDiscountClaimTransaction.InventTransId   = salesLine.InventTransId;
        gupDiscountClaimTransaction.ItemNumber      = itemId;
        gupDiscountClaimTransaction.insert();
    }
    else
    {
        gupDiscountClaimTransaction.selectForUpdate(true);
        gupDiscountClaimTransaction.Amount += _amount;
        gupDiscountClaimTransaction.update();
    }

}

protected void addledgerVoucherTransPair(LedgerVoucherObject _ledgerVoucherObject, LedgerPostingType _ledgerPostingType, LedgerDimensionAccount _creditAccount, LedgerDimensionAccount _debitAccount, Amount _amount, CurrencyExchangeHelper _exchangeRateHelper) { LedgerVoucherTransObject ledgerPostingTransaction = LedgerVoucherTransObject::newTransactionAmountDefault( _ledgerVoucherObject, _ledgerPostingType, _creditAccount, salesPurchLine.salesPurchLineInterface().parmCurrencyCode(), -1 * _amount, _exchangeRateHelper);
ledgerVoucher.addTrans(ledgerPostingTransaction);
ledgerPostingTransaction = LedgerVoucherTransObject::newTransactionAmountDefault( _ledgerVoucherObject, _ledgerPostingType, _debitAccount, salesPurchLine.salesPurchLineInterface().parmCurrencyCode(), _amount, _exchangeRateHelper);
ledgerVoucher.addTrans(ledgerPostingTransaction); }

protected void afterLinePost()
{
    next afterLinePost();

    // If revenue recognition schedule is set for sales line, skip trade agreement sales revenue posting.
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) && !this.isProforma())
    {
        if (salesLine.RevRecRevenueScheduleID)
        {
            info("@GlobalUnifiedPricing:UseStandardSalesLineAmountPostingWithRevRecRevenueScheduleIDSet");
        }
        else
        {
            this.postSalesTradeAgreement();
            this.postMarginComponentAdjustments();
        }
    }
}

protected void postMarginComponentAdjustments()
{
    if (!GUPParameters::find().PostMarginComponentAdjustments)
    {
        return;
    }

    GUPPriceComponentCodeSetup priceComponentCodeSetup;

    GUPMarginComponentAdjustmentHistory adjustmentHistory;

    LedgerVoucher ledgerVoucherLocal = this.getLedgerVoucher();
    LedgerVoucherObject ledgerVoucherObject = ledgerVoucherLocal.findLedgerVoucherObject();

    CurrencyExchangeHelper exchangeRateHelper = CurrencyExchangeHelper::newExchangeDate(Ledger::primaryLedger(CompanyInfo::findDataArea(curext()).RecId), ledgerVoucherObject.parmAccountingDate());
    exchangeRateHelper.parmExchangeRate1(this.fixedExchRate());
    exchangeRateHelper.parmExchangeRate2(this.fixedExchRateSecondary());

    while select Amount, MarginComponentCode from adjustmentHistory
        join PostInLedger, LedgerDimension from priceComponentCodeSetup
            where adjustmentHistory.InventTransId == SalesLine.InventTransId
                && priceComponentCodeSetup.PriceComponentCodeName == adjustmentHistory.MarginComponentCode
                && (!priceTreeEnabled || (priceComponentCodeSetup.PricingTree == gupPriceTreeRecId))
                && priceComponentCodeSetup.PostInLedger == NoYes::Yes
    {
        RecId ledgerDimensionId = priceComponentCodeSetup.LedgerDimension;

        if (!ledgerDimensionId)
        {
            ledgerDimensionId = GUPParameters::find().MarginComponentAdjustmentDefaultLedgerDimension;
        }

        LedgerDimensionAccount ledgerDimensionMerged = this.getLedgerDimensionLineAmount();

        LedgerVoucherTransObject ledgerVoucherTransObject = LedgerVoucherTransObject::newTransactionAmountDefault(
            ledgerVoucherObject,
            LedgerPostingType::SalesRevenue,
            ledgerDimensionMerged,
            salesLine.CurrencyCode,
            updateNow * adjustmentHistory.Amount,
            exchangeRateHelper);

        ledgerVoucherLocal.addTrans(ledgerVoucherTransObject);

        ledgerDimensionMerged = LedgerDimensionFacade::serviceCreateLedgerDimension(ledgerDimensionId, salesLine.DefaultDimension);

        ledgerVoucherTransObject = LedgerVoucherTransObject::newTransactionAmountDefault(
            ledgerVoucherObject,
            LedgerPostingType::SalesRevenue,
            ledgerDimensionMerged,
            salesLine.CurrencyCode,
            -updateNow * adjustmentHistory.Amount,
            exchangeRateHelper);

        ledgerVoucherLocal.addTrans(ledgerVoucherTransObject);
    }

}

protected void postSalesTradeAgreement()
{
    if (!GUPParameters::find().PostSalesTradeAgreementPrice)
    {
        return;
    }

    GUPPriceComponentCodeSetup priceComponentCodeSetup;
    GUPPriceComponentCode priceComponentCode;

    select firstonly PostInLedger, LedgerDimension from priceComponentCodeSetup
        exists join priceComponentCode 
            where priceComponentCode.Name == priceComponentCodeSetup.PriceComponentCodeName
                && priceComponentCode.PriceComponent == GUPPriceComponent::SalesTradeAgreement
                && (!priceTreeEnabled || (priceComponentCodeSetup.PricingTree == gupPriceTreeRecId));

    if (priceComponentCodeSetup.RecId && !priceComponentCodeSetup.PostInLedger)
    {
        return;
    }

    RecId ledgerDimensionId = priceComponentCodeSetup.LedgerDimension;

    if (!ledgerDimensionId)
    {
        ledgerDimensionId = GUPParameters::find().SalesTradeAgreementPriceDefaultLedgerDimension;
    }

    MCRPriceHistory priceHistory;
    MCRPriceHistoryRef priceHistoryRef;

    select firstonly RecId, Amount from priceHistory
        exists join priceHistoryRef
            where priceHistory.RecId                            == priceHistoryRef.PriceHistoryRecId
                && priceHistory.PriceHistoryType                == MCRPriceHistoryType::TradePrice
                && priceHistoryRef.mcrOrderLine2PriceHistoryRef == SalesLine.mcrOrderLine2PriceHistoryRef;

    if (!priceHistory.RecId)
    {
        return;
    }

    LedgerVoucher ledgerVoucherLocal = this.getLedgerVoucher();

    LedgerVoucherObject ledgerVoucherObject = ledgerVoucherLocal.findLedgerVoucherObject();

    CurrencyExchangeHelper exchangeRateHelper = CurrencyExchangeHelper::newExchangeDate(Ledger::primaryLedger(CompanyInfo::findDataArea(curext()).RecId), ledgerVoucherObject.parmAccountingDate());
    exchangeRateHelper.parmExchangeRate1(this.fixedExchRate());
    exchangeRateHelper.parmExchangeRate2(this.fixedExchRateSecondary());

    LedgerDimensionAccount ledgerDimensionMerged = this.getLedgerDimensionLineAmount();

    LedgerVoucherTransObject ledgerVoucherTransObject = LedgerVoucherTransObject::newTransactionAmountDefault(
        ledgerVoucherObject,
        LedgerPostingType::SalesRevenue,
        ledgerDimensionMerged,
        salesLine.CurrencyCode,
        updateNow * priceHistory.Amount,
        exchangeRateHelper);

    ledgerVoucherLocal.addTrans(ledgerVoucherTransObject);

    ledgerDimensionMerged = LedgerDimensionFacade::serviceCreateLedgerDimension(ledgerDimensionId, salesLine.DefaultDimension);

    ledgerVoucherTransObject = LedgerVoucherTransObject::newTransactionAmountDefault(
        ledgerVoucherObject,
        LedgerPostingType::SalesRevenue,
        ledgerDimensionMerged,
        salesLine.CurrencyCode,
        -updateNow * priceHistory.Amount,
        exchangeRateHelper);

    ledgerVoucherLocal.addTrans(ledgerVoucherTransObject);
}
